import { AsyncPipe, NgIf } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  Output,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { QChipComponent } from '@questrade/allspark-angular-components/chip';
import {
  QDropmenuComponent,
  QDropmenuOption,
  QDropmenuOriginDirective,
} from '@questrade/allspark-angular-components/dropmenu';
import { QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QInteractiveIconComponent } from '@questrade/allspark-angular-components/interactive-icon';
import { chevronLeft, chevronRight } from '@questrade/allspark-icons/icons';
import { BehaviorSubject } from 'rxjs';
import { QItemsInfoPosition } from './types/items-info-position.type';

@Component({
  selector: 'q-paginator',
  imports: [
    NgIf,
    AsyncPipe,
    QInteractiveIconComponent,
    QChipComponent,
    QDropmenuComponent,
    QDropmenuOriginDirective,
  ],
  templateUrl: './paginator.component.html',
  styleUrls: ['./paginator.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QPaginatorComponent {
  @Output() readonly changed = new EventEmitter<number>();

  @Input() itemsInfoPosition: QItemsInfoPosition = 'left';
  @Input({ transform: booleanAttribute }) showPagesInfo = true;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-paginator';

  @Input() get currentPage(): number {
    return this._currentPage;
  }
  set currentPage(value: number) {
    if (value < 1) {
      this._currentPage = 1;
    } else if (value > this._getNumberOfPages()) {
      this._currentPage = this._getNumberOfPages();
    } else {
      this._currentPage = value;
    }

    this._cd.detectChanges();
    this._updateLabels();
  }

  @Input() get totalItems(): number {
    return this._totalItems;
  }
  set totalItems(value: number) {
    this._totalItems = value || 0;
    this._updateLabels();
  }

  @Input() get pageSize(): number {
    return this._pageSize;
  }
  set pageSize(value: number) {
    this._pageSize = value < 1 ? 1 : value;
    this._updateLabels();
  }

  @HostBinding('class') _hostClass = 'q-paginator';

  _currentPageFirstItem$ = new BehaviorSubject<number>(0);
  _currentPageLastItem$ = new BehaviorSubject<number>(0);
  _numberOfPages$ = new BehaviorSubject<number>(0);
  _dropdownOptions: QDropmenuOption<number>[] = [];

  private _currentPage = 1;
  private _totalItems = 0;
  private _pageSize = 25;
  private readonly _cd = inject(ChangeDetectorRef);
  private readonly _iconRegistry = inject(QIconRegistryService);

  constructor() {
    this._iconRegistry.registerIcons([chevronLeft, chevronRight]);
  }

  _changePage(event: QDropmenuOption<number> | QDropmenuOption<number>[]): void {
    const pageValue = (event as QDropmenuOption<number>)?.value;

    if (pageValue <= this._getNumberOfPages()) {
      this.currentPage = pageValue;
      this.changed.emit(this.currentPage);
    }
  }

  _goNextPage(): void {
    if (!this._isLastPage()) {
      this.currentPage++;
      this.changed.emit(this.currentPage);
    }
  }

  _goPreviousPage(): void {
    if (!this._isFirstPage()) {
      this.currentPage--;
      this.changed.emit(this.currentPage);
    }
  }

  _isFirstPage(): boolean {
    return this.currentPage === 1;
  }

  _isLastPage(): boolean {
    return this.currentPage === this._getNumberOfPages();
  }

  private _getNumberOfPages(): number {
    return this.pageSize ? Math.ceil(this.totalItems / this.pageSize) || 1 : 1;
  }

  private _updateLabels(): void {
    this._currentPageFirstItem$.next(
      this.totalItems ? (this.currentPage - 1) * this.pageSize + 1 : 0,
    );

    const lastPossible = this.currentPage * this.pageSize;

    this._currentPageLastItem$.next(
      this.totalItems > lastPossible ? lastPossible : this.totalItems,
    );

    this._numberOfPages$.next(this._getNumberOfPages() || 1);

    this._updatePagesOptions();
  }

  private _updatePagesOptions(): void {
    this._dropdownOptions = Array(this._getNumberOfPages() || 1)
      .fill(null)
      .map((_, index) => ({
        value: index + 1,
        label: (index + 1).toString(),
      }));
  }
}
